const items = $input.all();
return items.map(({json}) => {
  const body = json.body || json;
  const name = String(body.name || '').trim().slice(0,100);
  const service = String(body.service || '').trim().slice(0,100);
  const email = String(body.email || '').toLowerCase().trim().slice(0,150);
  const phone = String(body.phone || '').replace(/[^0-9]/g,'').slice(-15);
  const message = String(body.message || '').slice(0,1000);
  const channel = String(body.channel || 'website').slice(0,60);
  const budget = Math.max(0,Math.min(10000000,Number(body.budget) || 0));
  const consent = body.consent === true || body.consent === 'true';
  const errors = [];
  if (!name) errors.push('name is required');
  if (!service) errors.push('service is required');
  if (!email && phone.length < 9) errors.push('email or a valid phone is required');
  let score = 0;
  if (phone.length >= 9) score += 20;
  if (service.length > 3) score += 15;
  if (budget >= 500) score += 25;
  if (/urgent|today|this week|عاجل|مستعجل|الأسبوع/i.test(message)) score += 30;
  if (/website|form|ads|نموذج الموقع|إعلان ممول/.test(channel)) score += 10;
  const priority = score >= 70 ? 'high' : score >= 45 ? 'medium' : 'normal';
  const idempotencyKey = email ? 'email:' + email : 'phone:' + phone;
  return {json:{ok:errors.length===0,errors,lead:{name,service,email,phone,message,channel,budget,consent},score,priority,idempotency_key:idempotencyKey,next_step:errors.length ? 'manual_review' : 'persist_and_assign_followup'}};
});
